export function translate(language: InterfaceLanguage, source: string): string {
  if (language === 'en') return source;
  const key = source.replace(/\s+/g, ' ').trim();
  if (!key) return source;
  const translated = messages[language][key];
  if (!translated) return source;
  const leadingSpace = /^\s/.test(source) ? ' ' : '';
  const trailingSpace = /\s$/.test(source) ? ' ' : '';
  return `${leadingSpace}${translated}${trailingSpace}`;
}

export function formatCurrency(amount: number, currency: BusinessCurrency, language: InterfaceLanguage): string {
  const locale = language === 'pt-BR' ? 'pt-BR' : language === 'es' ? 'es-ES' : 'en-US';
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(amount);
}
